# ---- Figure 4.3: footprint regression with intervals -----------------------

foot_model <- lm(Footprint ~ GDPperCapita, data = hp_complete)

x_seq <- seq(0, 120000, length.out = 200)
band <- data.frame(GDPperCapita = x_seq)
ci <- predict(foot_model, band, interval = "confidence")
pi <- predict(foot_model, band, interval = "prediction")
band$fit <- ci[, "fit"]
band$ci_lwr <- ci[, "lwr"]
band$ci_upr <- ci[, "upr"]
band$pi_lwr <- pi[, "lwr"]
band$pi_upr <- pi[, "upr"]

p43 <- ggplot() +
  geom_ribbon(
    data = band,
    aes(
      x = GDPperCapita, ymin = pi_lwr, ymax = pi_upr,
      fill = "95% prediction interval"
    ),
    alpha = 0.18, colour = NA
  ) +
  geom_ribbon(
    data = band,
    aes(
      x = GDPperCapita, ymin = ci_lwr, ymax = ci_upr,
      fill = "95% confidence interval"
    ),
    alpha = 0.35, colour = NA
  ) +
  geom_point(
    data = hp_complete, aes(x = GDPperCapita, y = Footprint),
    shape = 21, size = 1.6, fill = book_palette[["blue"]],
    colour = BOOK_INK, stroke = 0.25, alpha = 0.55
  ) +
  geom_line(
    data = band, aes(x = GDPperCapita, y = fit),
    colour = BOOK_INK, linewidth = 0.9
  ) +
  scale_fill_manual(
    values = c(
      "95% prediction interval" = book_palette[["orange"]],
      "95% confidence interval" = book_palette[["sky_blue"]]
    ),
    name = NULL
  ) +
  scale_x_continuous(labels = label_comma()) +
  coord_cartesian(xlim = c(0, 120000), ylim = c(0, 45)) +
  labs(x = "GDP per capita", y = "Ecological footprint") +
  book_theme()

save_book_fig(
  p43,
  chapter = 4, id = "4.3", type = "scatter",
  slug = "footprint_regression_intervals",
  caption = paste(
    "Simple linear regression of ecological footprint on GDP per capita for",
    "143 countries. The dark line is the fitted regression. The narrow band",
    "is the 95% confidence interval for the mean footprint; the wide band is",
    "the 95% prediction interval for an individual country."
  ),
  alt = paste(
    "Scatterplot of ecological footprint against GDP per capita for 143",
    "countries, with a rising regression line. A narrow shaded band hugs the",
    "line and a much wider shaded band surrounds it, widening at higher",
    "incomes."
  ),
  direct_labels = TRUE,
  author_note = paste(
    "The model uses the 143 countries with a non-missing GDPperCapita. The",
    "prediction interval extends below zero at the lowest incomes, which is",
    "not physically possible for a footprint, so the y-axis starts at zero."
  )
)

# ---- Chapter 4 values -------------------------------------------------------

coef_rows <- function(fit) {
  tab <- summary(fit)$coefficients
  data.frame(
    term = rownames(tab),
    estimate = tab[, "Estimate"],
    se = tab[, "Std. Error"],
    t = tab[, "t value"],
    p = tab[, "Pr(>|t|)"],
    check.names = FALSE, row.names = NULL
  )
}

model_record <- function(fit) {
  f <- summary(fit)$fstatistic
  list(
    n = nobs(fit),
    r_squared = summary(fit)$r.squared,
    adjusted_r_squared = summary(fit)$adj.r.squared,
    f = unname(f[1]),
    df1 = unname(f[2]),
    df2 = unname(f[3]),
    p = pf(f[1], f[2], f[3], lower.tail = FALSE),
    coefficients = coef_rows(fit)
  )
}

slope_ci <- as.data.frame(confint(foot_model))
slope_ci$term <- rownames(slope_ci)
rownames(slope_ci) <- NULL
names(slope_ci)[1:2] <- c("lower_95", "upper_95")

pred_ci <- as.data.frame(predict(
  foot_model, data.frame(GDPperCapita = 70000), interval = "confidence"
))
pred_pi <- as.data.frame(predict(
  foot_model, data.frame(GDPperCapita = 70000), interval = "prediction"
))
prediction_70000 <- data.frame(
  interval = c("confidence", "prediction"),
  fit = c(pred_ci$fit, pred_pi$fit),
  lower_95 = c(pred_ci$lwr, pred_pi$lwr),
  upper_95 = c(pred_ci$upr, pred_pi$upr)
)

log_model <- lm(LifeExpectancy ~ log10(GDPperCapita), data = hp_complete)

values <- list(
  data = list(
    file = "happy_planet_index_2024.csv",
    total_countries = nrow(hp),
    complete_cases = nrow(hp_complete),
    missing_gdp = sum(is.na(hp$GDPperCapita))
  ),
  figure_4_1 = list(
    note = "Illustrative exponential curves; no dataset is used."
  ),
  figure_4_2 = list(
    note = "Scatterplot of GDP per capita and life expectancy; n = 143 complete cases."
  ),
  figure_4_3 = list(
    note = paste(
      "Regression of Footprint on GDPperCapita with confidence and prediction",
      "intervals; n = 143."
    )
  ),
  footprint_model = c(
    list(model = "lm(Footprint ~ GDPperCapita, data = hp_complete)"),
    model_record(foot_model),
    list(
      r = cor(hp_complete$GDPperCapita, hp_complete$Footprint),
      slope_ci = slope_ci,
      prediction_at_70000 = prediction_70000
    )
  ),
  log_life_expectancy_model = c(
    list(model = "lm(LifeExpectancy ~ log10(GDPperCapita), data = hp_complete)"),
    model_record(log_model)
  )
)

save_book_values(
  chapter = 4,
  values = values,
  conventions = list(
    note = paste(
      "Ordinary least squares. The life-expectancy model uses a base-10",
      "logarithm of GDPperCapita. The complete-case sample is 143 countries;",
      "4 countries in the CSV have no GDPperCapita."
    )
  ),
  source = "r_code/figures/chapter_04.R"
)
